{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.08);--accent:#7dd3fc;--muted:#cbd5e1;--glass-border:rgba(255,255,255,0.12)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--muted);background:radial-gradient(1000px 600px at 10% 10%, rgba(29,78,216,0.12), transparent), linear-gradient(180deg,#071023 0%, #071023 100%);}
    .site{min-height:100vh;display:flex;flex-direction:column;background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#60a5fa);box-shadow:0 6px 18px rgba(2,6,23,0.6);display:flex;align-items:center;justify-content:center;font-weight:700;color:#04263b}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600}
    main{flex:1;display:flex;flex-direction:column;gap:28px;padding:28px;max-width:1100px;margin:0 auto;width:100%}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:24px;align-items:start}
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid var(--glass-border);backdrop-filter:blur(8px);padding:22px;border-radius:14px}
    h1{color:#e6eef8;margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:#bcd3e8}
    .cta{display:flex;gap:12px;margin-top:16px}
    .btn{background:linear-gradient(90deg,var(--accent),#60a5fa);border:none;padding:10px 14px;border-radius:10px;color:#022;cursor:pointer;font-weight:700}
    .secondary{background:transparent;border:1px solid var(--glass-border);padding:8px 12px;border-radius:10px;color:var(--muted)}
    .small{font-size:13px;color:#9fb0c8}
    .columns{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
    ul{padding-left:18px}
    .benefits li{margin-bottom:10px}
    .process{display:flex;flex-direction:column;gap:10px}
    .step{display:flex;gap:12px;align-items:flex-start}
    .number{width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,0.03);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    /* Proof Gallery */
    .proof{display:flex;flex-direction:column;gap:12px}
    .testimonial{min-height:90px;padding:14px;border-radius:10px;background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);border:1px solid var(--glass-border)}
    .badges{display:flex;gap:10px;align-items:center}
    .badge{display:inline-flex;align-items:center;gap:8px;padding:8px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid var(--glass-border);cursor:default;position:relative}
    .badge svg{width:18px;height:18px}
    .tooltip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);white-space:nowrap;background:#071023;padding:8px;border-radius:6px;border:1px solid var(--glass-border);font-size:12px;display:none}
    .badge:hover .tooltip{display:block}
    /* Accordion */
    .accordion{margin-top:8px}
    .acc-item{border-radius:10px;overflow:hidden;border:1px solid var(--glass-border);background:var(--card)}
    .acc-header{padding:12px;display:flex;justify-content:space-between;align-items:center;cursor:pointer}
    .acc-body{padding:12px;border-top:1px solid rgba(255,255,255,0.02);display:none}
    footer{padding:20px;border-top:1px solid rgba(255,255,255,0.02);display:flex;justify-content:space-between;align-items:center}
    .crisis{font-size:13px;color:#ffdcdc;background:#3b0710;padding:10px;border-radius:8px}
    @media(max-width:900px){.hero{grid-template-columns:1fr}.columns{grid-template-columns:1fr}.badges{flex-wrap:wrap}}
  </style>
</head>
<body>
  <div class="site">
    <header>
      <div class="brand">
        <div class="logo">T</div>
        <div>
          <div style="color:#dff5ff;font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Overview</a>
        <a href="specialties.html">Modalities</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Rates</a>
        <a href="book.html">Book</a>
        <a href="faq.html">Questions</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="card">
          <h1>Clinical therapy with clear structure and human respect</h1>
          <p class="lead">I offer focused therapy that keeps safety, confidentiality, and practical planning at the center. We work together to name what matters and test small changes that fit your life.</p>
          <div class="cta">
            <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="secondary" href="contact.html">Message my practice</a>
          </div>
          <p class="small" style="margin-top:12px">Sessions are 50 minutes by default. Alternate formats can be discussed during intake.</p>
        </div>

        <aside class="card">
          <div style="font-weight:700;color:#e6eef8">About me</div>
          <p class="small" style="margin-top:8px">I combine evidence-informed methods with pragmatic planning. My work centers assessment, collaboration, and steady tracking of progress.
          </p>

          <div style="margin-top:12px">
            <div style="font-weight:700;color:#cfeffd">Proof & Credentials</div>
            <div class="proof" aria-live="polite" id="proof-rotator">
              <div class="testimonial" id="testimonial">""</div>
              <div class="badges" id="badges"></div>
            </div>
          </div>
        </aside>
      </section>

      <section class="card">
        <div style="font-weight:700;color:#e6eef8">Where I focus — clear areas of practice</div>
        <div class="columns" style="margin-top:12px">
          <div>
            <ul class="benefits">
              <li><strong>Life transitions</strong> — navigating role, relationship, and career shifts with pragmatic goals.</li>
              <li><strong>Relationship patterns</strong> — live problem-solving for communication and boundary work.</li>
              <li><strong>Anxiety & stress regulation</strong> — practical tools to reduce overwhelm and improve functioning.</li>
            </ul>
          </div>
          <div>
            <ul class="benefits">
              <li><strong>Low mood and motivation</strong> — structured approaches to regain energy for valued activity.</li>
              <li><strong>Parenting & family concerns</strong> — strategy and support for family rhythms and coping.</li>
            </ul>
          </div>
        </div>
      </section>

      <section class="card">
        <div style="font-weight:700;color:#e6eef8">How a typical engagement proceeds</div>
        <div class="process" style="margin-top:12px">
          <div class="step"><div class="number">1</div><div><strong>Contact & intake</strong> — brief call to identify fit and plan next steps.</div></div>
          <div class="step"><div class="number">2</div><div><strong>Initial assessment</strong> — a few sessions to map patterns and priorities.</div></div>
          <div class="step"><div class="number">3</div><div><strong>Targeted work</strong> — focused interventions and measurable checks.</div></div>
          <div class="step"><div class="number">4</div><div><strong>Review & next steps</strong> — regular pauses to reassess and adapt the plan.</div></div>
        </div>
      </section>

      <section class="card">
        <div style="font-weight:700;color:#e6eef8">Confidentiality, boundaries, and limits</div>
        <div class="accordion" id="conf-accordion">
          <div class="acc-item">
            <div class="acc-header" data-target="confidentiality">Confidentiality
              <span aria-hidden>▾</span>
            </div>
            <div class="acc-body" id="confidentiality">
              <p class="small">Sessions are confidential. I will not disclose your information without your written consent except where required by law (e.g., imminent risk of harm to self or others, suspected abuse). Notes are kept securely.</p>
            </div>
          </div>

          <div class="acc-item">
            <div class="acc-header" data-target="scope">Scope & limits of practice
              <span aria-hidden>▾</span>
            </div>
            <div class="acc-body" id="scope">
              <p class="small">My work is psychotherapy and coaching within a private practice setting. I do not provide medical diagnosis or emergency services. When needs exceed outpatient therapy, I will discuss appropriate referrals.</p>
            </div>
          </div>

          <div class="acc-item">
            <div class="acc-header" data-target="sessions">Session boundaries
              <span aria-hidden>▾</span>
            </div>
            <div class="acc-body" id="sessions">
              <p class="small">Standard sessions are 50 minutes. Scheduling, cancellations, and remote options are discussed at intake. I maintain clear boundaries around communication outside sessions to preserve clinical clarity.</p>
            </div>
          </div>
        </div>
      </section>

      <section class="card" style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-weight:700;color:#e6eef8">Ready to begin focused work?</div>
          <div class="small" style="margin-top:6px">If it feels right, we can schedule a time to talk and establish a plan that fits your life.</div>
        </div>
        <div style="text-align:right">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <div class="small" style="margin-top:8px;color:#9fb0c8">Prefer email? <a href="mailto:{{EMAIL}}" style="color:var(--accent)">Send a note</a></div>
        </div>
      </section>

    </main>

    <footer>
      <div class="small">&copy; <span id="year"></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
      <div class="crisis">If you are in immediate danger, call emergency services (911) or your local emergency number. In the U.S., you can call or text 988 for the Suicide & Crisis Lifeline. This practice does not provide crisis services.</div>
    </footer>
  </div>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    // Proof Gallery data
    const testimonials = [
      {text: 'Therapy here gave me practical steps I could try between sessions and a real sense of steady progress.', name: 'A. — client'},
      {text: 'Clear, thoughtful, and direct. I appreciated the emphasis on measurable change and realistic goals.', name: 'R. — client'},
      {text: 'Compassionate without being vague. My therapist helped me see patterns and test alternatives.', name: 'M. — client'}
    ];

    const badges = [
      {title: 'Licensed Clinician', tooltip: 'State-licensed therapist with years of outpatient experience', svg: '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="9" stroke="#60a5fa" stroke-width="1.5"/><path d="M8 12l2.2 2.4L16 9" stroke="#60a5fa" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'},
      {title: 'Continuing Education', tooltip: 'Ongoing training in contemporary therapeutic practice', svg: '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="5" width="18" height="14" rx="2" stroke="#7dd3fc" stroke-width="1.5"/><path d="M7 9h10M7 13h6" stroke="#7dd3fc" stroke-width="1.4" stroke-linecap="round"/></svg>'},
      {title: 'HIPAA-aligned', tooltip: 'Records and communications follow secure practice standards', svg: '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2v4" stroke="#93c5fd" stroke-width="1.5" stroke-linecap="round"/><path d="M4 8v10a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8" stroke="#93c5fd" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/><rect x="8" y="11" width="8" height="5" rx="1" stroke="#93c5fd" stroke-width="1.5"/></svg>'}
    ];

    // Rotator
    let index = 0;
    const tEl = document.getElementById('testimonial');
    const badgesEl = document.getElementById('badges');

    function renderProof(i){
      const t = testimonials[i % testimonials.length];
      tEl.innerHTML = `<div style=\"color:#cfeffd;font-weight:700;margin-bottom:6px\">${t.name}</div><div style=\"color:#bfd9ee\">${t.text}</div>`;
      badgesEl.innerHTML = '';
      badges.forEach(b=>{
        const span = document.createElement('span');
        span.className = 'badge';
        span.innerHTML = b.svg + `<div style=\"font-size:13px;color:#dff5ff;font-weight:600\">${b.title}</div>` + `<div class=\"tooltip\">${b.tooltip}</div>`;
        badgesEl.appendChild(span);
      });
    }

    renderProof(0);
    setInterval(()=>{ index++; renderProof(index); }, 5000);

    // Accordion behavior
    document.querySelectorAll('.acc-header').forEach(h=>{
      h.addEventListener('click', ()=>{
        const target = document.getElementById(h.getAttribute('data-target'));
        const open = target.style.display === 'block';
        document.querySelectorAll('.acc-body').forEach(b=>b.style.display='none');
        if(!open) target.style.display = 'block';
      });
    });
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Modalities & Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071027;--glass:rgba(255,255,255,0.06);--accent:#a78bfa;--muted:#cbd5e1}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:#031025;color:var(--muted)}
    .wrap{max-width:1100px;margin:24px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    .nav a{color:var(--muted);margin-left:16px;text-decoration:none;font-weight:600}
    .glass{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.08);backdrop-filter:blur(10px);padding:18px;border-radius:12px}
    h1{color:#e9eefb;margin:0}
    .lead{margin-top:8px;color:#bcd3e8}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:16px;margin-top:16px}
    .list{display:flex;flex-direction:column;gap:12px}
    .service{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03)}
    .rate{font-weight:700;color:#e6eef8}
    .cta{margin-top:12px}
    .btn{background:linear-gradient(90deg,var(--accent),#7c3aed);border:none;padding:10px 12px;border-radius:10px;color:#021;cursor:pointer;font-weight:700}
    /* rotating testimonials & badges (different layout) */
    .rotator{display:flex;flex-direction:column;gap:8px}
    .quote{font-style:italic;color:#dbeafe;padding:10px;border-radius:8px;background:rgba(255,255,255,0.01);border:1px solid rgba(255,255,255,0.02)}
    .badge-row{display:flex;gap:8px;flex-wrap:wrap}
    .badge-pill{background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);padding:8px;border-radius:999px;position:relative}
    .badge-pill .tip{position:absolute;top:-40px;left:50%;transform:translateX(-50%);display:none;background:#041223;padding:6px;border-radius:6px;border:1px solid rgba(255,255,255,0.06);font-size:12px}
    .badge-pill:hover .tip{display:block}
    /* accordion small */
    .acc{margin-top:12px}
    .acc button{width:100%;text-align:left;padding:10px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);cursor:pointer}
    .acc .panel{display:none;padding:10px;border-top:1px solid rgba(255,255,255,0.02);color:#bcd3e8}
    footer{margin-top:20px;color:#9fb0c8;font-size:13px}
    @media(max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:800;color:#e6eef8">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:#9fb0c8">Therapeutic offerings for adults</div>
      </div>
      <nav class="nav">
        <a href="index.html">Overview</a>
        <a href="specialties.html">Modalities</a>
        <a href="approach.html">How I Work</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main style="margin-top:16px">
      <section class="glass">
        <h1>Practical formats for measurable progress</h1>
        <p class="lead">I offer structured formats to meet different goals: ongoing care, focused intensives, and targeted skill packages. Each is framed around clear objectives rather than vague promises.</p>
      </section>

      <div class="grid">
        <div>
          <div class="list">
            <div class="service">
              <div style="display:flex;justify-content:space-between;align-items:center"><div><strong>Weekly Therapy</strong><div class="small" style="color:#9fb0c8">Classic outpatient rhythm</div></div><div class="rate">Standard rates apply</div></div>
              <div class="small" style="margin-top:8px">Ongoing work for longer-term patterns and steady progress. Sessions focus on assessment, skills practice, and goal review.</div>
            </div>

            <div class="service">
              <div style="display:flex;justify-content:space-between;align-items:center"><div><strong>Concentrated Focus Session</strong><div class="small" style="color:#9fb0c8">A single extended appointment for a specific problem</div></div><div class="rate">Program-style pricing</div></div>
              <div class="small" style="margin-top:8px">A 2–3 hour, agenda-driven session to map a problem, rehearse approaches, and agree on immediate next steps you can try.</div>
            </div>

            <div class="service">
              <div style="display:flex;justify-content:space-between;align-items:center"><div><strong>Short-term Coaching Bundle</strong><div class="small" style="color:#9fb0c8">6-session, goal-focused package</div></div><div class="rate">Package options available</div></div>
              <div class="small" style="margin-top:8px">For clearer, present-focused goals where skill-building and accountability are the priority. We define outcomes at the start and review progress formally.</div>
            </div>

            <div class="service">
              <div style="display:flex;justify-content:space-between;align-items:center"><div><strong>Couples & Relational Short Work</strong><div class="small" style="color:#9fb0c8">Focused sessions for concrete shifts</div></div><div class="rate">Independent consults</div></div>
              <div class="small" style="margin-top:8px">Short-term, neutral facilitation to shift interaction patterns and clarify next steps for a relationship.</div>
            </div>
          </div>

          <div class="acc" style="margin-top:12px">
            <button aria-expanded="false" id="acc-toggle">Session logistics & policies</button>
            <div class="panel" id="acc-panel">
              <p>Scheduling, cancellations, and payment are handled through the intake process. I aim for transparent, written expectations so we both know how we’ll work together.</p>
            </div>
          </div>
        </div>

        <aside class="glass">
          <div style="font-weight:700;color:#e6eef8">Proof Gallery</div>
          <div class="rotator" id="rotator">
            <div class="quote" id="quote">""</div>
            <div class="badge-row" id="badgeRow"></div>
            <div style="margin-top:8px"><a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
          </div>

          <div style="margin-top:12px;font-size:13px;color:#9fb0c8">Interested in pricing details? Rates are discussed during intake so we can match format to need.</div>
        </aside>
      </div>

      <footer>
        <div style="display:flex;justify-content:space-between;align-items:center;gap:12px">
          <div style="max-width:700px">This practice emphasizes clear, ethical care. If you are in crisis call emergency services or your local crisis line. Clinical scope and confidentiality are discussed at intake.</div>
          <div style="text-align:right"><a href="contact.html" style="color:var(--accent);text-decoration:none;font-weight:700">Contact to discuss fit</a></div>
        </div>
      </footer>
    </main>
  </div>

  <script>
    // Testimonials and badge data (different set/order than about)
    const quotes = [
      {q: 'A focused session helped me move past a block and make practical steps the next week.', by: 'S.'},
      {q: 'The short-term bundle gave me tools and accountability. It felt efficient and respectful of my time.', by: 'L.'},
      {q: 'Clear boundaries and direct feedback made therapy feel meaningful and useful.', by: 'K.'}
    ];

    const badgeData = [
      {label:'State License', tip:'Licensed clinician in {{STATE}}'},
      {label:'Ongoing Training', tip:'Regular professional development and supervision'},
      {label:'Secure Records', tip:'Practice follows privacy best practices'}
    ];

    let i=0; const qEl=document.getElementById('quote'), bEl=document.getElementById('badgeRow');
    function rotate(){
      const item = quotes[i % quotes.length];
      qEl.innerHTML = `<span style=\"font-weight:700;color:#dff5ff\">${item.by}</span> — ${item.q}`;
      bEl.innerHTML = '';
      badgeData.forEach(b=>{
        const sp = document.createElement('div'); sp.className='badge-pill'; sp.innerHTML = `<span style=\"font-weight:700;color:#dfe8ff;margin-right:8px\">•</span>${b.label}<div class=\"tip\">${b.tip}</div>`; bEl.appendChild(sp);
      });
      i++;
    }
    rotate(); setInterval(rotate,4500);

    // small accordion
    const accBtn = document.getElementById('acc-toggle'), accPanel = document.getElementById('acc-panel');
    accBtn.addEventListener('click', ()=>{
      const open = accPanel.style.display === 'block';
      accPanel.style.display = open ? 'none' : 'block';
      accBtn.setAttribute('aria-expanded', String(!open));
    });
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#041022;--glass:rgba(255,255,255,0.04);--accent:#34d399;--muted:#c9d7e6}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:linear-gradient(180deg,#021026,#03192b);color:var(--muted)}
    .container{max-width:1000px;margin:24px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);margin-left:14px;text-decoration:none;font-weight:600}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.06);padding:18px;border-radius:12px;margin-top:12px}
    h1{color:#e6f7f1;margin:0}
    .sub{margin-top:8px;color:#bfeee0}
    .flow{display:grid;grid-template-columns:1fr 300px;gap:16px;margin-top:16px}
    .card{background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);padding:14px;border-radius:10px}
    .steps{display:flex;flex-direction:column;gap:10px}
    .step{display:flex;gap:12px}
    .dot{width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,0.02);display:flex;align-items:center;justify-content:center;color:var(--accent);font-weight:700}
    .conf{margin-top:12px}
    .conf .acc-item{margin-bottom:8px;border-radius:8px;overflow:hidden}
