          <div class="small">&copy; {{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
        </div>
      </footer>
    </main>
  </div>

  <script>
    // Slim proof gallery with different testimonial rotation and credential tooltips
    const slimTestimonials = [
      {q: 'A steady, pragmatic approach — I felt seen and given doable steps.', by: 'P.'},
      {q: 'Direct, professional, and humane. Progress was measured and clear.', by: 'J.'}
    ];
    const credentials = [
      {label:'Licensed', info:'State license in {{STATE}}'},
      {label:'Training', info:'Ongoing specialized training in adult psychotherapy'},
      {label:'Secure', info:'Privacy and record safeguards in place'}
    ];

    let s = 0;
    const testCard = document.getElementById('testCard');
    const credList = document.getElementById('credList');

    function renderSlim(){
      const item = slimTestimonials[s % slimTestimonials.length];
      testCard.innerHTML = `<strong style=\"color:#dfffea\">${item.by}</strong> — <span style=\"color:#d0efe3\">${item.q}</span>`;
      credList.innerHTML = '';
      credentials.forEach(c=>{
        const d = document.createElement('div');
        d.textContent = c.label;
        d.title = c.info; // simple tooltip on hover
        credList.appendChild(d);
      });
    }
    renderSlim(); setInterval(()=>{ s++; renderSlim(); },5500);

    // accordion for confidentiality
    document.querySelectorAll('.conf .acc-item button').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const id = btn.getAttribute('data-target');
        const body = document.getElementById(id);
        const open = body.style.display === 'block';
        document.querySelectorAll('.conf .acc-item .body').forEach(b=>b.style.display='none');
        body.style.display = open ? 'none' : 'block';
      });
    });
  </script>
